#!/usr/bin/env bash
# Pixel-art Clawd walking across a waybar custom module.
# Frames and position classes come from clawd.css (see gen.py).
# Click (SIGUSR1) makes him hop and turn around.

DIR=$(dirname "$(readlink -f "$0")")
# track size as generated by gen.py
read -r MAX STEP < <(sed -n 's|.*clawd: max=\([0-9]*\) step=\([0-9]*\).*|\1 \2|p' "$DIR/clawd.css")
DELAY=${CLAWD_DELAY:-0.07}

WALK=(0 1 0 2)   # walk cycle: stand, step a, stand, step b

pos=0
dir=1
tick=0
pause=0
hop=0

trap 'dir=$(( -dir )); hop=6' USR1

while :; do
    (( dir > 0 )) && d=r || d=l

    if (( hop > 0 )); then
        frame=hop-$d
        (( hop-- ))
    elif (( pause > 0 )); then
        # stop, look at the user, blink, look back
        case $pause in
            12|11|3|2) frame=blink-c ;;
            *) frame=look-c ;;
        esac
        (( pause-- ))
    else
        frame=walk-$d-${WALK[tick / 2 % 4]}
        (( pos += dir * STEP ))
        if (( pos <= 0 )); then pos=0; dir=1; fi
        if (( pos >= MAX )); then pos=$MAX; dir=-1; fi
        (( RANDOM % 120 == 0 )) && pause=30
    fi
    (( tick++ ))

    printf '{"text":" ","tooltip":"Clawd","class":["f-%s","p-%d"]}\n' "$frame" "$pos"

    sleep "$DELAY" & wait $!
done
